-- 073_plain_words_for_remaining_credit_prices.sql
--
-- Plain words on the rest of the credit price list (fixer pass, 2026-10-08).
-- 072 rewrote the 18 descriptions that named a model. Read back from dev on
-- 2026-10-08, the price list an owner reads (Settings -> ARGUS data plan ->
-- What credits cost) still carried internal wording on other rows: a model
-- name, a person's name and an unpriced proposal on the background remover,
-- "pattern match" and "PLATFORM cost" on the chat name reader, "No model call"
-- on the page publisher, "CTA" and "not metered" on the older website builder
-- rows, and eight rows with no description at all. The page no longer prints
-- the action's key, so the description is the only thing that says what the
-- credit buys; every active row needs one, in plain words.
--
-- One UPDATE per action type, in BOTH pricing homes (argus.action_pricing and
-- lumen.argus_action_pricing; the 065 rule). A row only in one home is a
-- no-op UPDATE in the other.
-- GUARDED: a row is changed only while its description is empty, is still the
-- old seeded text, or still carries one of the internal words below, so a
-- description somebody has since rewritten by hand is left alone, and running
-- this twice changes nothing the second time.
-- The last statement in each home SELECTs the count of active rows whose
-- description is still empty or still carries an internal word, so the
-- pipeline log shows 0 (an action type this file does not list shows here).
--
-- NOTHING HERE BELONGS TO ONE BUSINESS: these are platform price rows.
-- Idempotent; safe to pre-apply before the code push.
--
-- TARGET DB: iadm_services.

IF OBJECT_ID('argus.action_pricing','U') IS NOT NULL
BEGIN
  UPDATE argus.action_pricing SET description = N'ARGUS website chat: puts a chat answer into your voice before your visitor reads it.', updated_at = SYSUTCDATETIME()
   WHERE action_type = N'argus.reply_voice_rewrite' AND (description IS NULL OR description LIKE N'%Claude%' OR description LIKE N'%Sonnet%' OR description LIKE N'%Haiku%' OR description LIKE N'%GPT%' OR description LIKE N'%u2net%' OR description LIKE N'%Brandon%' OR description LIKE N'%PROPOSED%' OR description LIKE N'%pattern match%' OR description LIKE N'%model call%' OR description LIKE N'%self-hosted%' OR description LIKE N'%Intelligence Layer%' OR description LIKE N'%PLATFORM cost%' OR description LIKE N'%client-billed%' OR description LIKE N'%audited%' OR description LIKE N'%metered%' OR description LIKE N'%Portal%' OR description LIKE N'%tenant%' OR description LIKE N'%agent%' OR description LIKE N'%class%' OR description COLLATE Latin1_General_CS_AS LIKE N'%IL %' OR description COLLATE Latin1_General_CS_AS LIKE N'%CTA%');
