  DECLARE @left INT = (SELECT COUNT(*) FROM argus.action_pricing WHERE is_active = 1 AND (description IS NULL OR description LIKE N'%Claude%' OR description LIKE N'%Sonnet%' OR description LIKE N'%Haiku%' OR description LIKE N'%GPT%' OR description LIKE N'%u2net%' OR description LIKE N'%Brandon%' OR description LIKE N'%PROPOSED%' OR description LIKE N'%pattern match%' OR description LIKE N'%model call%' OR description LIKE N'%self-hosted%' OR description LIKE N'%Intelligence Layer%' OR description LIKE N'%PLATFORM cost%' OR description LIKE N'%client-billed%' OR description LIKE N'%audited%' OR description LIKE N'%metered%' OR description LIKE N'%Portal%' OR description LIKE N'%tenant%' OR description LIKE N'%agent%' OR description LIKE N'%class%' OR description COLLATE Latin1_General_CS_AS LIKE N'%IL %' OR description COLLATE Latin1_General_CS_AS LIKE N'%CTA%'));
  PRINT CONCAT('  = argus.action_pricing: ', @left, ' active description(s) still empty or not in plain words');
  SELECT N'argus.action_pricing' AS pricing_home, @left AS still_not_plain;
